rs.slice(0, limit) : avatars;\n    const remainingCount = limit ? Math.max(0, avatars.length - limit) : 0;\n\n    return (\n      <div\n        ref={ref}\n        className={cn(\"moonui-theme\", \"flex items-center\", className)}\n        {...props}\n      >\n        <div className=\"flex\">\n          {visibleAvatars.map((avatar, index) => (\n            <div \n              key={index} \n              className=\"relative\"\n              style={{ \n                marginLeft: index === 0 ? 0 : `${overlapOffset}px`,\n                zIndex: visibleAvatars.length - index \n              }}\n            >\n              {avatar}\n            </div>\n          ))}\n          {remainingCount > 0 && (\n            <div \n              className=\"relative z-0\"\n              style={{ marginLeft: `${overlapOffset}px` }}\n            >\n              <Avatar variant=\"border\">\n                <AvatarFallback>\n                  +{remainingCount}\n                </AvatarFallback>\n              </Avatar>\n            </div>\n          )}\n        </div>\n      </div>\n    );\n  }\n);\nAvatarGroup.displayName = \"AvatarGroup\";\n\nexport { Avatar, AvatarImage, AvatarFallback, AvatarGroup };\n","import * as React from 'react';\nimport { createContextScope } from '@radix-ui/react-context';\nimport { useCallbackRef } from '@radix-ui/react-use-callback-ref';\nimport { useLayoutEffect } from '@radix-ui/react-use-layout-effect';\nimport { Primitive } from '@radix-ui/react-primitive';\nimport { useIsHydrated } from '@radix-ui/react-use-is-hydrated';\n\nimport type { Scope } from '@radix-ui/react-context';\n\n/* -------------------------------------------------------------------------------------------------\n * Avatar\n * -----------------------------------------------------------------------------------------------*/\n\nconst AVATAR_NAME = 'Avatar';\n\ntype ScopedProps<P> = P & { __scopeAvatar?: Scope };\nconst [createAvatarContext, createAvatarScope] = createContextScope(AV