erts a callback to a ref to avoid triggering re-renders when passed as a\n * prop or avoid re-executing effects when passed as a dependency\n */\nfunction useCallbackRef<T extends (...args: any[]) => any>(callback: T | undefined): T {\n  const callbackRef = React.useRef(callback);\n\n  React.useEffect(() => {\n    callbackRef.current = callback;\n  });\n\n  // https://github.com/facebook/react/issues/19240\n  return React.useMemo(() => ((...args) => callbackRef.current?.(...args)) as T, []);\n}\n\nexport { useCallbackRef };\n","import { useSyncExternalStore } from 'use-sync-external-store/shim';\n\n/**\n * Determines whether or not the component tree has been hydrated.\n */\nexport function useIsHydrated() {\n  return useSyncExternalStore(\n    subscribe,\n    () => true,\n    () => false\n  );\n}\n\nfunction subscribe() {\n  return () => {};\n}\n","\"use client\"\n\nimport * as React from \"react\";\nimport { cva, type VariantProps } from \"class-variance-authority\";\nimport { cn } from \"../../lib/utils\";\n\n/**\n * Premium Badge Component\n * \n * Durum, kategori ve etiketleme için yüksek kaliteli badge bileşeni.\n * Dark ve light modda uyumlu, erişilebilir ve çeşitli varyantlar sunar.\n */\n\nconst badgeVariants = cva(\n  [\"inline-flex items-center justify-center gap-1.5\", \n  \"font-medium transition-colors duration-200\", \n  \"border focus:outline-none\",\n  \"focus-visible:ring-2 focus-visible:ring-offset-1\",\n  // Auto spacing between badges\n  \"mr-2 mb-2 last:mr-0\"],\n  {\n    variants: {\n      variant: {\n        primary: [\n          \"border-transparent bg-gray-900 text-white\",\n          \"hover:bg-gray-800 dark:hover:bg-gray-700\",\n          \"focus-visible:ring-gray-500/30 dark:focus-visible:ring-gray-400/40\",\n          \"dark:bg-gray-700 dark:text-gray-50 dark:shadow-inner dark:shadow-gray-950/10\",\n        ],\n        secondary: [\n          \"border-transparent bg-secondary text-secondary-foreground\",\n          \"hover:bg-gray-200 dark:hover:bg-gray-600\",\n          \"focus-visible:ring-gray-400/30 dark:focus-visible:ring-gray-500/40\",\n          \"dark:bg-gray-700/50 dark:text-gray-50 dark:shadow-inner dark:shadow-gray-950/10\",\n        ],\n        outline: [\n          \"border-gray-200 dark:border-gray-600\",\n          \"bg-transparent text-foreground\",\n          \"hover:border-gray-300 dark:hover:border-gray-500\",\n          \"focus-visible:ring-gray-400/30 dark:focus-visible:ring-gray-500/40\",\n          \"dark:text-gray-100 dark:bg-transparent dark:backdrop-blur-sm\",\n        ],\n        destructive: [\n          \"border-transparent bg-error text-white\",\n          \"hover:bg-error/90 dark:hover:bg-error/80\",\n          \"focus-visible:ring-error/30 dark:focus-visible:ring-error/25\",\n          \"dark:bg-error/90 dark:text-white dark:shadow-inner dark:shadow-error/10\",\n        ],\n        success: [\n          \"border-transparent bg-success text-white\",\n          \"hover:bg-success/90 dark:hover:bg-success/80\",\n          \"focus-visible:ring-success/30 dark:focus-visible:ring-success/25\",\n          \"dark:bg-success/90 dark:text-white dark:shadow-inner dark:shadow-success/10\",\n        ],\n        warning: [\n          \"border-transparent bg-warning text-white\",\n          \"hover:bg-warning/90 dark:hover:bg-warning/80\",\n          \"focus-visible:ring-warning/30 dark:focus-visible:ring-warning/25\",\n          \"dark:bg-warning/90 dark:text-gray-900 dark:shadow-inner dark:shadow-warning/10\",\n        ],\n        ghost: [\n          \"border border-gray-200 bg-gray-50/50 text-gray-700\",\n          \"hover:bg-gray-100 dark:hover:bg-gray-800/60\",\n          \"focus-visible:ring-gray-400/30 dark:focus-visible:ring-gray-500/40\",\n          \"dark:border-gray-700 dark:bg-gray-800/30 dark:text-gray-300\",\n          \"transition-all duration-200\",\n        ],\n        pro: [\n          \"border-transparent bg-gradient-to-r from-purple-600 to-pink-600 text-white\",\n          \"hover:from-purple-700 hover:to-pink-700\",\n          \"focus-visible:ring-purple-400/30 dark:focus-visible:ring-purple-500/40\",\n          \"shadow-md dark:shadow-lg dark:shadow-purple-500/10\",\n        ],\n        admin: [\n          \"border-transparent bg-gradient-to-r from-purple-600 to-pink-600 text-white\",\n          \"hover:from-purple-700 hover:to-pink-700\", \n          \"focus-visible:ring-purple-400/30 dark:focus-visible:ring-purple-500/40\",\n          \"shadow-md dark:shadow-lg dark:shadow-purple-500/10\",\n        ],\n      },\n      size: {\n        sm: \"h-5 px-2 text-xs\",\n        md: \"h-6 px-3 text-sm\",\n        lg: \"h-8 px-4 text-base\",\n      },\n      radius: {\n        default: \"rounded-full\",\n        sm: \"rounded-md\",\n        lg: \"rounded-xl\",\n        none: \"rounded-none\",\n      }\n    },\n    defaultVariants: {\n      variant: \"primary\",\n      size: \"md\",\n      radius: \"default\",\n    },\n  }\n);\n\nexport interface BadgeProps\n  extends React.HTMLAttributes<HTMLDivElement>,\n    Omit<VariantProps<typeof badgeVariants>, 'variant'> {\n  withDot?: boolean;\n  dotColor?: string;\n  removable?: boolean;\n  onRemove?: () => void;\n  leftIcon?: React.ReactNode;\n  rightIcon?: React.ReactNode;\n  variant?: 'primary' | 'secondary' | 'destructive' | 'outline' | 'success' | 'warning' | 'ghost' | 'pro' | 'admin';\n  /** Disable automatic spacing between badges */\n  noAutoSpacing?: boolean;\n}\n\n/**\n * Premium Badge Component\n * \n * @param props - Badge bileşeni özellikleri\n * @param props.variant - Badgenin görsel varyantı\n * @param props.size - Badge boyutu\n * @param props.radius - Köşe yuvarlama stili\n * @param props.withDot - Başında nokta gösterimi\n * @param props.dotColor - Noktanın rengi (özel)\n * @param props.removable - Kaldırılabilir badge (X simgesi ile)\n * @param props.onRemove - Kaldırma işlevi\n * @param props.leftIcon - Badge'in solunda görüntülenecek ikon\n * @param props.rightIcon - Badge'in sağında görüntülenecek ikon\n * @param props.noAutoSpacing - Otomatik spacing'i devre dışı bırak\n */\nfunction Badge({\n  className,\n  variant,\n  size,\n  radius,\n  withDot,\n  dotColor,\n  removable,\n  onRemove,\n  leftIcon,\n  rightIcon,\n  noAutoSpacing,\n  children,\n  ...props\n}: BadgeProps) {\n  // Auto-assign icons and content for special variants\n  let autoLeftIcon = leftIcon;\n  let autoChildren = children;\n  \n  if (variant === 'pro') {\n    // Auto Sparkles icon for pro\n    autoLeftIcon = leftIcon || (\n      <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" className=\"w-3 h-3\">\n        <path d=\"M12 0L13.09 8.26L22 9L13.09 9.74L12 18L10.91 9.74L2 9L10.91 8.26L12 0Z\" fill=\"currentColor\"/>\n        <path d=\"M19 5L19.5 7L21 7.5L19.5 8L19 10L18.5 8L17 7.5L18.5 7L19 5Z\" fill=\"currentColor\"/>\n        <path d=\"M19 15L19.5 17L21 17.5L19.5 18L19 20L18.5 18L17 17.5L18.5 17L19 15Z\" fill=\"currentColor\"/>\n      </svg>\n    );\n    autoChildren = children || 'Pro';\n  }\n  \n  if (variant === 'admin') {\n    // Auto CheckCircle icon for admin\n    autoLeftIcon = leftIcon || (\n      <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" className=\"w-3 h-3\">\n        <path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z\" fill=\"currentColor\"/>\n      </svg>\n    );\n    autoChildren = children || 'Admin Pro';\n  }\n\n  return (\n    <div \n      className={cn(\n        \"moonui-theme\", \n        badgeVariants({ variant, size, radius }), \n        // Remove auto-spacing if noAutoSpacing is true\n        noAutoSpacing && \"mr-0 mb-0\",\n        className\n      )} \n      data-removable={removable ? \"\" : undefined}\n      {...props}\n    >\n      {withDot && (\n        <span \n          className={cn(\n            \"h-2 w-2 rounded-full\", \n            dotColor || \n              (variant === \"destructive\" ? \"bg-white\" :\n               variant === \"success\" ? \"bg-white\" :\n               variant === \"warning\" ? \"bg-white\" :\n               variant === \"secondary\" ? \"bg-secondary-foreground\" :\n               variant === \"outline\" ? \"bg-foreground\" :\n               variant === \"ghost\" ? \"bg-foreground\" :\n               variant === \"pro\" ? \"bg-white\" :\n               variant === \"admin\" ? \"bg-white\" :\n               \"bg-primary-foreground\")\n          )} \n          aria-hidden=\"true\"\n        />\n      )}\n      {autoLeftIcon && (\n        <span className=\"inline-flex shrink-0 items-center\">\n          {autoLeftIcon}\n        </span>\n      )}\n      <span className=\"inline-flex items-center\">{autoChildren}</span>\n      {rightIcon && (\n        <span className=\"inline-flex shrink-0 items-center\">\n          {rightIcon}\n        </span>\n      )}\n      {removable && onRemove && (\n        <button \n          type=\"button\"\n          className=\"ml-1 -mr-1 h-3.5 w-3.5 rounded-full inline-flex items-center justify-center hover:bg-black/10 dark:hover:bg-white/10\"\n          onClick={(e) => {\n            e.stopPropagation();\n            onRemove();\n          }}\n          aria-label=\"Remove badge\"\n        >\n          <svg \n            width=\"8\" \n            height=\"8\" \n            viewBox=\"0 0 8 8\" \n            fill=\"none\" \n            xmlns=\"http://www.w3.org/2000/svg\"\n            className=\"opacity-70\"\n            aria-hidden=\"true\"\n          >\n            <path d=\"M0.799988 7.19999L7.19999 0.799988M0.799988 0.799988L7.19999 7.19999\" stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/>\n          </svg>\n        </button>\n      )}\n    </div>\n  );\n}\n\nexport { Badge, badgeVariants };\n","\"use client\"\n\nimport * as React from \"react\";\nimport { ChevronRight, MoreHorizontal } from \"lucide-react\";\nimport { cva, type VariantProps } from \"class-variance-authority\";\n\nimport { cn } from \"../../lib/utils\";\n\nconst breadcrumbVariants = cva(\n  \"flex items-center gap-1.5 text-sm\",\n  {\n    variants: {\n      variant: {\n        default: \"text-foreground transition-colors\",\n        muted: \"text-muted-foreground transition-colors\",\n        ghost: \"text-foreground/60 transition-colors\",\n      },\n      size: {\n        default: \"text-sm\",\n        sm: \"text-xs\",\n        lg: \"text-base\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n);\n\ninterface BreadcrumbProps\n  extends React.HTMLAttributes<HTMLElement>,\n    VariantProps<typeof breadcrumbVariants> {\n  separator?: React.ReactNode;\n  showHomeIcon?: boolean;\n}\n\ninterface BreadcrumbListProps extends React.HTMLAttributes<HTMLOListElement> {\n  collapsed?: boolean;\n  collapsedWidth?: number;\n}\n\ninterface BreadcrumbItemProps extends React.HTMLAttributes<HTMLLIElement> {\n  isCurrent?: boolean;\n  href?: string;\n  asChild?: boolean;\n}\n\ninterface BreadcrumbSeparatorProps extends React.HTMLAttributes<HTMLSpanElement> {\n  /** Custom separator icon or text */\n  icon?: React.ReactNode;\n}\n\ninterface BreadcrumbEllipsisProps extends React.HTMLAttributes<HTMLSpanElement> {\n  /** Custom ellipsis icon */\n  icon?: React.ReactNode;\n}\n\nconst Breadcrumb = React.forwardRef<HTMLElement, BreadcrumbProps>(\n  ({ className, variant, size, ...props }, ref) => (\n    <nav\n      ref={ref}\n      className={cn(\"moonui-theme\", breadcrumbVariants({ variant, size }), className)}\n      aria-label=\"breadcrumb\"\n      {...props}\n    />\n  )\n);\nBreadcrumb.displayName = \"Breadcrumb\";\n\nconst BreadcrumbList = React.forwardRef<HTMLOListElement, BreadcrumbListProps>(\n  ({ className, collapsed, collapsedWidth = 3, ...props }, ref) => {\n    const childrenArray = React.Children.toArray(props.children).filter(Boolean);\n    const childCount = childrenArray.length;\n\n    if (collapsed && childCount > collapsedWidth) {\n      const firstItem = childrenArray[0];\n      // const middleItems = childrenArray.slice(1, -2); // Uncomment when needed\n      const lastTwoItems = childrenArray.slice(-2);\n\n      return (\n        <ol\n          ref={ref}\n          className={cn(\n            \"flex flex-wrap items-center gap-1.5 sm:gap-2.5\",\n            className\n          )}\n          {...props}\n        >\n          {firstItem}\n          <BreadcrumbEllipsis />\n          {lastTwoItems}\n        </ol>\n      );\n    }\n\n    return (\n      <ol\n        ref={ref}\n        className={cn(\n          \"flex flex-wrap items-center gap-1.5 sm:gap-2.5\",\n          className\n        )}\n        {...props}\n      />\n    );\n  }\n);\nBreadcrumbList.displayName = \"BreadcrumbList\";\n\nconst BreadcrumbItem = React.forwardRef<HTMLLIElement, BreadcrumbItemProps>(\n  ({ className, isCurrent, href, asChild = false, ...props }, ref) => {\n    const Comp = asChild ? React.Fragment : href ? \"a\" : \"span\";\n    const itemProps = asChild ? {} : href ? { href } : {};\n\n    return (\n      <li\n        ref={ref}\n        className={cn(\"moonui-theme\", \"inline-flex items-center gap-1.5\", className)}\n        aria-current={isCurrent ? \"page\" : undefined}\n        {...props}\n      >\n        <Comp \n          className={cn(\n            \"transition-colors duration-200 hover:text-foreground\",\n            isCurrent \n              ? \"font-medium text-foreground\" \n              : \"text-muted-foreground hover:text-foreground hover:underline hover:underline-offset-4 hover:decoration-muted-foreground/30\"\n          )}\n          {...itemProps}\n        >\n          {props.children}\n        </Comp>\n      </li>\n    );\n  }\n);\nBreadcrumbItem.displayName = \"BreadcrumbItem\";\n\nconst BreadcrumbSeparator = ({\n  children,\n  className,\n  ...props\n}: BreadcrumbSeparatorProps) => (\n  <span\n    role=\"presentation\"\n    aria-hidden=\"true\"\n    className={cn(\"moonui-theme\", \"text-muted-foreground opacity-70\", className)}\n    {...props}\n  >\n    {children || <ChevronRight className=\"h-3.5 w-3.5\" />}\n  </span>\n);\nBreadcrumbSeparator.displayName = \"BreadcrumbSeparator\";\n\nconst BreadcrumbEllipsis = ({\n  className,\n  ...props\n}: BreadcrumbEllipsisProps) => (\n  <span\n    role=\"presentation\"\n    aria-hidden=\"true\"\n    className={cn(\"moonui-theme\", \"flex items-center text-muted-foreground hover:text-foreground/80 transition-colors duration-200\", className)}\n    {...props}\n  >\n    <MoreHorizontal className=\"h-4 w-4\" />\n    <span className=\"sr-only\">More pages</span>\n  </span>\n);\nBreadcrumbEllipsis.displayName = \"BreadcrumbEllipsis\";\n\nconst BreadcrumbLink = React.forwardRef<HTMLAnchorElement, React.AnchorHTMLAttributes<HTMLAnchorElement>>(\n  ({ className, href, ...props }, ref) => (\n    <a\n      ref={ref}\n      href={href}\n      className={cn(\n        \"transition-colors duration-200 hover:text-foreground text-muted-foreground hover:underline hover:underline-offset-4 hover:decoration-muted-foreground/30\",\n        className\n      )}\n      {...props}\n    />\n  )\n);\nBreadcrumbLink.displayName = \"BreadcrumbLink\";\n\nconst BreadcrumbPage = React.forwardRef<HTMLSpanElement, React.HTMLAttributes<HTMLSpanElement>>(\n  ({ className, ...props }, ref) => (\n    <span\n      ref={ref}\n      className={cn(\n        \"font-medium text-foreground dark:text-white dark:text-opacity-95\",\n        className\n      )}\n      {...props}\n    />\n  )\n);\nBreadcrumbPage.displayName = \"BreadcrumbPage\";\n\nexport {\n  Breadcrumb,\n  BreadcrumbList,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n  BreadcrumbEllipsis,\n};\n","\"use client\"\n\nimport * as React from \"react\";\nimport { cva, type VariantProps } from \"class-variance-authority\";\nimport { cn } from \"../../lib/utils\";\nimport { Loader2 } from \"lucide-react\";\n\n/**\n * Premium Button Component\n * \n * A world-class, accessible, and versatile button component.\n * Pixel-perfect design with extensive variants and states.\n */\nconst buttonVariants = cva(\n  [\"inline-flex items-center justify-center gap-2 whitespace-nowrap\",\n  \"font-medium relative\",\n  \"transition-all duration-200 ease-out\",\n  \"transform active:scale-[0.98]\",\n  \"focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2\",\n  \"disabled:opacity-50 disabled:cursor-not-allowed disabled:pointer-events-none disabled:transform-none\"],\n  {\n    variants: {\n      variant: {\n        primary: [\n          \"bg-primary text-primary-foreground\",\n          \"dark:bg-primary dark:text-primary-foreground\",\n          \"hover:bg-primary/90 dark:hover:bg-primary/90\",\n          \"active:bg-primary/80 dark:active:bg-primary/80\",\n          \"shadow-sm hover:shadow-md\",\n          \"focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\",\n          \"transition-all duration-200\",\n        ],\n        secondary: [\n          \"bg-gray-100 text-gray-900\",\n          \"dark:bg-gray-800 dark:text-gray-100\",\n          \"hover:bg-gray-200 dark:hover:bg-gray-700\",\n          \"active:bg-gray-300 dark:active:bg-gray-600\",\n          \"border border-gray-200 dark:border-gray-700\",\n          \"focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\",\n          \"shadow-sm hover:shadow-md\",\n        ],\n        outline: [\n          \"bg-background text-foreground\",\n          \"dark:bg-background dark:text-foreground\",\n          \"border border-input dark:border-input\",\n          \"hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent dark:hover:text-accent-foreground\",\n          \"active:bg-accent/80 dark:active:bg-accent/80\",\n          \"focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\",\n          \"transition-all duration-200\",\n        ],\n        ghost: [\n          \"text-gray-700\",\n          \"dark:text-gray-300\",\n          \"hover:bg-gray-100 hover:text-gray-900 dark:hover:bg-gray-800 dark:hover:text-gray-100\",\n          \"active:bg-gray-200 dark:active:bg-gray-700\",\n          \"focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\",\n          \"transition-all duration-200\",\n        ],\n        destructive: [\n          \"bg-destructive text-destructive-foreground\",\n          \"dark:bg-destructive dark:text-destructive-foreground\",\n          \"hover:bg-destructive/90 dark:hover:bg-destructive/90\",\n          \"active:bg-destructive/80 dark:active:bg-destructive/80\",\n          \"shadow-sm hover:shadow-md\",\n          \"focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\",\n          \"transition-all duration-200\",\n        ],\n        success: [\n          \"bg-success text-success-foreground\",\n          \"dark:bg-success dark:text-success-foreground\",\n          \"hover:bg-success/90 dark:hover:bg-success/90\",\n          \"active:bg-success/80 dark:active:bg-success/80\",\n          \"shadow-sm hover:shadow-md\", \n          \"focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2\",\n          \"transition-all duration-200\",\n        ],\n        link: [\n          \"text-primary bg-transparent\",\n          \"underline-offset-4 hover:underline\",\n          \"hover:text-primary/80 active:text-primary/70\",\n          \"p-0 h-auto\",\n          \"transition-colors duration-200\",\n        ],\n        gradient: [\n          \"bg-gradient-to-r from-purple-500 to-pink-500 text-white\",\n          \"hover:from-purple-600 hover:to-pink-600\",\n          \"active:from-purple-700 active:to-pink-700\",\n          \"shadow-xl shadow-purple-500/40\",\n          \"hover:shadow-2xl hover:shadow-purple-500/50\",\n          \"focus-visible:ring-purple-500/50\",\n          \"transition-all duration-300\",\n        ],\n        glow: [\n          \"bg-blue-500 text-white\",\n          \"shadow-[0_0_30px_rgba(59,130,246,0.5)]\",\n          \"hover:shadow-[0_0_40px_rgba(59,130,246,0.7)]\",\n          \"active:shadow-[0_0_20px_rgba(59,130,246,0.4)]\",\n          \"hover:bg-blue-600\",\n          \"focus-visible:ring-blue-500/50\",\n          \"transition-all duration-300\",\n        ],\n        soft: [\n          \"bg-primary/10 text-primary\",\n          \"hover:bg-primary/20\",\n          \"active:bg-primary/30\",\n          \"focus-visible:ring-primary/50\",\n          \"dark:bg-primary/20 dark:text-primary-foreground\",\n          \"dark:hover:bg-primary/30 dark:active:bg-primary/40\",\n          \"transition-colors duration-200\",\n        ],\n        glass: [\n          \"bg-white/10 backdrop-blur-md text-foreground\",\n          \"border border-white/20\",\n          \"hover:bg-white/20 hover:border-white/30\",\n          \"active:bg-white/30\",\n          \"shadow-lg\",\n          \"focus-visible:ring-white/50\",\n          \"dark:bg-gray-800/10 dark:border-gray-700/20\",\n          \"dark:hover:bg-gray-800/20 dark:hover:border-gray-700/30\",\n          \"transition-all duration-200\",\n        ],\n        neon: [\n          \"bg-transparent text-green-400\",\n          \"border-2 border-green-400\",\n          \"hover:bg-green-400 hover:text-gray-900\",\n          \"hover:shadow-[0_0_30px_rgba(74,222,128,0.6)]\",\n          \"active:shadow-[0_0_15px_rgba(74,222,128,0.4)]\",\n          \"focus-visible:ring-green-400/50\",\n          \"transition-all duration-300\",\n        ],\n      },\n      size: {\n        xs: \"h-7 px-2.5 text-xs\",\n        sm: \"h-8 px-3 text-sm\",\n        md: \"h-10 px-4 text-base\",\n        lg: \"h-12 px-6 text-lg\",\n        xl: \"h-14 px-8 text-xl\",\n        icon: \"h-10 w-10 p-2\",\n        \"icon-sm\": \"h-8 w-8 p-1.5\",\n        \"icon-lg\": \"h-12 w-12 p-3\",\n      },\n      rounded: {\n        default: \"rounded-xl\",\n        full: \"rounded-full\",\n        none: \"rounded-none\",\n        sm: \"rounded-lg\",\n        lg: \"rounded-2xl\",\n      },\n      fullWidth: {\n        true: \"w-full\",\n      },\n    },\n    defaultVariants: {\n      variant: \"primary\",\n      size: \"md\",\n      rounded: \"default\",\n      fullWidth: false,\n    },\n  }\n);\n\n// Button component props\nexport interface ButtonProps\n  extends React.ButtonHTMLAttributes<HTMLButtonElement>,\n    VariantProps<typeof buttonVariants> {\n  asChild?: boolean;\n  loading?: boolean;\n  leftIcon?: React.ReactNode;\n  rightIcon?: React.ReactNode;\n}\n\n/**\n * Premium Button Component\n * \n * @param props - Button component properties\n * @param props.variant - Visual variant (primary, secondary, ghost, etc.)\n * @param props.size - Button size (xs, sm, md, lg, xl)\n * @param props.loading - Loading state display\n * @param props.leftIcon - Icon on the left side\n * @param props.rightIcon - Icon on the right side\n * @param props.fullWidth - Full width display\n * @param props.rounded - Corner rounding style (default, full, none)\n * @param props.asChild - For Radix UI polymorphic component\n */\nconst Button = React.forwardRef<HTMLButtonElement, ButtonProps>(\n  ({ \n    className, \n    variant, \n    size, \n    rounded, \n    fullWidth,\n    asChild = false,\n    loading = false,\n    leftIcon,\n    rightIcon,\n    children,\n    disabled,\n    ...props \n  }, ref) => {\n    // Radix UI'ın asChild pattern'i için - \"as\" prop yerine\n    const Comp = asChild ? \"button\" : \"button\";\n    \n    return (\n      <Comp\n        className={cn(\"moonui-theme\", buttonVariants({ variant, size, rounded, fullWidth, className }))}\n        ref={ref}\n        disabled={disabled || loading}\n        data-loading={loading ? \"\" : undefined}\n        {...props}\n      >\n        {loading && (\n          <Loader2 className=\"w-4 h-4 animate-spin\" aria-hidden=\"true\" />\n        )}\n        {!loading && leftIcon}\n        {children}\n        {!loading && rightIcon}\n      </Comp>\n    );\n  }\n);\n\nButton.displayName = \"Button\";\n\nexport { Button, buttonVariants };\n","\"use client\"\n\nimport * as React from \"react\";\nimport { cva, type VariantProps } from \"class-variance-authority\";\nimport { motion, type HTMLMotionProps } from \"framer-motion\";\nimport { cn } from \"../../lib/utils\";\nimport { microInteractionVariants, hoverAnimations, tapAnimations } from \"@/lib/micro-interactions\";\n\nconst cardVariants = cva(\n  \"rounded-lg border bg-card text-card-foreground shadow-sm dark:shadow-gray-900/20 dark:border-gray-800 dark:bg-gray-900 dark:text-gray-100 transition-all duration-200\",\n  {\n    variants: {\n      variant: {\n        default: \"\",\n        outline: \"border border-border shadow-none bg-transparent dark:border-gray-700 dark:bg-transparent dark:text-gray-200\",\n        filled: \"border-none bg-secondary dark:bg-gray-800 dark:text-gray-100 dark:shadow-inner dark:shadow-gray-950/10\",\n        elevated: \"border-none shadow-md dark:shadow-lg dark:shadow-gray-900/30 dark:bg-gray-850 dark:text-gray-100\",\n        gradient: \"border-none bg-gradient-to-br from-primary/5 to-primary/10 dark:from-primary/10 dark:to-primary/20\",\n        glass: \"border border-white/20 bg-white/10 backdrop-blur-md dark:border-gray-700/30 dark:bg-gray-800/10\",\n      },\n      size: {\n        default: \"\",\n        sm: \"\",\n        lg: \"\",\n        xl: \"\",\n      },\n      radius: {\n        default: \"rounded-lg\",\n        sm: \"rounded-md\",\n        lg: \"rounded-xl\",\n        full: \"rounded-3xl\",\n        none: \"rounded-none\",\n      },\n      interactive: {\n        true: \"cursor-pointer hover:shadow-lg hover:border-primary/20 dark:hover:border-primary/30 hover:-translate-y-0.5 active:translate-y-0 active:shadow-sm\",\n        false: \"\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n      radius: \"def