nion-to-intersection/\ntype UnionToIntersection<T> = (T extends any ? (x: T) => any : never) extends (x: infer R) => any\n  ? R\n  : never;\n\nexport function useStateMachine<M>(\n  initialState: MachineState<M>,\n  machine: M & Machine<MachineState<M>>\n) {\n  return React.useReducer((state: MachineState<M>, event: MachineEvent<M>): MachineState<M> => {\n    const nextState = (machine[state] as any)[event];\n    return nextState ?? state;\n  }, initialState);\n}\n","import * as React from 'react';\n\ntype Direction = 'ltr' | 'rtl';\nconst DirectionContext = React.createContext<Direction | undefined>(undefined);\n\n/* -------------------------------------------------------------------------------------------------\n * Direction\n * -----------------------------------------------------------------------------------------------*/\n\ninterface DirectionProviderProps {\n  children?: React.ReactNode;\n  dir: Direction;\n}\nconst DirectionProvider: React.FC<DirectionProviderProps> = (props) => {\n  const { dir, children } = props;\n  return <DirectionContext.Provider value={dir}>{children}</DirectionContext.Provider>;\n};\n\n/* -----------------------------------------------------------------------------------------------*/\n\nfunction useDirection(localDir?: Direction) {\n  const globalDir = React.useContext(DirectionContext);\n  return localDir || globalDir || 'ltr';\n}\n\nconst Provider = DirectionProvider;\n\nexport {\n  useDirection,\n  //\n  Provider,\n  //\n  DirectionProvider,\n};\n","function clamp(value: number, [min, max]: [number, number]): number {\n  return Math.min(max, Math.max(min, value));\n}\n\nexport { clamp };\n","\"use client\"\n\nimport * as React from \"react\"\nimport { motion, useInView, useAnimation, Variants } from \"framer-motion\"\nimport { cn } from \"../../lib/utils\"\n\ninterface ScrollRevealProps {\n  children: React.ReactNode\n  direction?: \"up\" | \"down\" | \"left\" | \"right\"\n  delay?: number\n  duration?: number\n  distance?: number\n  threshold?: number\n  triggerOnce?: boolean\n  stagger?: number\n  className?: string\n  variants?: Variants\n  animate?: boolean\n  style?: React.CSSProperties\n  id?: string\n}\n\nconst defaultVariants: Record<string, Variants> = {\n  up: {\n    hidden: { opacity: 0, y: 50 },\n    visible: { opacity: 1, y: 0 }\n  },\n  down: {\n    hidden: { opacity: 0, y: -50 },\n    visible: { opacity: 1, y: 0 }\n  },\n  left: {\n    hidden: { opacity: 0, x: 50 },\n    visible: { opacity: 1, x: 0 }\n  },\n  right: {\n    hidden: { opacity: 0, x: -50 },\n    visible: { opacity: 1, x: 0 }\n  },\n  fade: {\n    hidden: { opacity: 0 },\n    visible: { opacity: 1 }\n  },\n  scale: {\n    hidden: { opacity: 0, scale: 0.8 },\n    visible: { opacity: 1, scale: 1 }\n  },\n  blur: {\n    hidden: { opacity: 0, filter: \"blur(10px)\" },\n    visible: { opacity: 1, filter: \"blur(0px)\" }\n  }\n}\n\nconst ScrollReveal = React.forwardRef<HTMLDivElement, ScrollRevealProps>(\n  ({\n    children,\n    direction = \"up\",\n    delay = 0,\n    duration = 0.6,\n    distance = 50,\n    threshold = 0.1,\n    triggerOnce = true,\n    stagger = 0,\n    className,\n    variants,\n    animate = true,\n    style,\n    id\n  }, ref) => {\n    const controls = useAnimation()\n    const elementRef = React.useRef<HTMLDivElement>(null)\n    const isInView = useInView(elementRef, { \n      amount: threshold,\n      once: triggerOnce\n    })\n\n    // Custom variants with distance\n    const customVariants = React.useMemo(() => {\n      if (variants) return variants\n      \n      const baseVariants = defaultVariants[direction] || defaultVariants.up\n      \n      return {\n        hidden: {\n          ...baseVariants.hidden,\n          ...(direction === \"up\" && { y: distance }),\n          ...(direction === \"down\" && { y: -distance }),\n          ...(direction === \"left\" && { x: distance }),\n          ...(direction === \"right\" && { x: -distance })\n        },\n        visible: baseVariants.visibl