le={style}\n        id={id}\n      >\n        {children}\n      </motion.div>\n    )\n  }\n)\n\nScrollRevealContainer.displayName = \"ScrollRevealContainer\"\n\n// ScrollReveal item for use within containers\ninterface ScrollRevealItemProps {\n  children: React.ReactNode\n  direction?: \"up\" | \"down\" | \"left\" | \"right\"\n  duration?: number\n  distance?: number\n  className?: string\n  variants?: Variants\n  style?: React.CSSProperties\n  id?: string\n}\n\nconst ScrollRevealItem = React.forwardRef<HTMLDivElement, ScrollRevealItemProps>(\n  ({\n    children,\n    direction = \"up\",\n    duration = 0.6,\n    distance = 50,\n    className,\n    variants,\n    style,\n    id\n  }, ref) => {\n    const customVariants = React.useMemo(() => {\n      if (variants) return variants\n      \n      const baseVariants = defaultVariants[direction] || defaultVariants.up\n      \n      return {\n        hidden: {\n          ...baseVariants.hidden,\n          ...(direction === \"up\" && { y: distance }),\n          ...(direction === \"down\" && { y: -distance }),\n          ...(direction === \"left\" && { x: distance }),\n          ...(direction === \"right\" && { x: -distance })\n        },\n        visible: baseVariants.visible\n      }\n    }, [direction, distance, variants])\n\n    return (\n      <motion.div\n        ref={ref}\n        variants={customVariants}\n        transition={{\n          duration,\n          ease: \"easeOut\"\n        }}\n        className={cn(className)}\n        style={style}\n        id={id}\n      >\n        {children}\n      </motion.div>\n    )\n  }\n)\n\nScrollRevealItem.displayName = \"ScrollRevealItem\"\n\nexport { ScrollReveal, ScrollRevealContainer, ScrollRevealItem }\nexport type { ScrollRevealProps, ScrollRevealContainerProps, ScrollRevealItemProps }","\"use client\"\n\nimport * as React from \"react\"\nimport * as SeparatorPrimitive from \"@radix-ui/react-separator\"\nimport { cva, type VariantProps } from \"class-variance-authority\"\n\nimport { cn } from \"../../lib/utils\"\n\nconst separatorVariants = cva(\n  \"shrink-0 bg-border\",\n  {\n    variants: {\n      orientation: {\n        horizontal: \"h-[1px] w-full\",\n        vertical: \"h-full w-[1px]\",\n      },\n      variant: {\n        default: \"bg-border\",\n        dashed: \"border-dashed border-border bg-transparent\",\n        dotted: \"border-dotted border-border bg-transparent\",\n        gradient: \"bg-gradient-to-r from-transparent via-border to-transparent\",\n      },\n      size: {\n        sm: \"\",\n        md: \"\",\n        lg: \"\",\n      },\n    },\n    compoundVariants: [\n      {\n        orientation: \"horizontal\",\n        variant: \"dashed\",\n        className: \"border-t h-0\",\n      },\n      {\n        orientation: \"vertical\",\n        variant: \"dashed\",\n        className: \"border-l w-0\",\n      },\n      {\n        orientation: \"horizontal\",\n        variant: \"dotted\",\n        className: \"border-t h-0\",\n      },\n      {\n        orientation: \"vertical\",\n        variant: \"dotted\",\n        className: \"border-l w-0\",\n      },\n      {\n        orientation: \"horizontal\",\n        size: \"sm\",\n        variant: [\"dashed\", \"dotted\"],\n        className: \"border-t-[0.5px]\",\n      },\n      {\n        orientation: \"horizontal\",\n        size: \"lg\",\n        variant: [\"dashed\", \"dotted\"],\n        className: \"border-t-2\",\n      },\n      {\n        orientation: \"vertical\",\n        size: \"sm\",\n        variant: [\"dashed\", \"dotted\"],\n        className: \"border-l-[0.5px]\",\n      },\n      {\n        orientation: \"vertical\",\n        size: \"lg\",\n        variant: [\"dashed\", \"dotted\"],\n        className: \"border-l-2\",\n      },\n      {\n        orientation: \"horizontal\",\n        size: \"sm\",\n        variant: [\"default\", \"gradient\"],\n        className: \"h-[0.5px]\",\n      },\n      {\n        orientation: \"horizontal\",\n        size: \"lg\",\n        variant: [\"default\", \"gradient\"],\n        className: \"h-[2px]\",\n      },\n      {\n        orientation: \"vertical\",\n        size: \"sm\",\n        variant: [\"default\", \"gradient\"],\n        className: \"w-[0.5px]\",\n      },\n      {\n        orientation: \"vertical\",\n        size: \"lg\",\n        variant: [\"default\", \"gradient\"],\n        className: \"w-[2px]\",\n      },\n    ],\n    defaultVariants: {\n      orientation: \"horizontal\",\n      variant: \"default\",\n      size: \"md\",\n    },\n  }\n)\n\nexport interface SeparatorProps\n  extends Omit<React.ComponentPropsWithoutRef<typeof SeparatorPrimitive.Root>, keyof VariantProps<typeof separatorVariants>>,\n    VariantProps<typeof separatorVariants> {}\n\nconst Separator = React.forwardRef<\n  React.ElementRef<typeof SeparatorPrimitive.Root>,\n  SeparatorProps\n>(\n  (\n    { \n      className, \n      orientation = \"horizontal\", \n      variant = \"default\",\n      size = \"md\",\n      decorative = true, \n      ...props \n    },\n    ref\n  ) => (\n    <SeparatorPrimitive.Root\n      ref={ref}\n      decorative={decorative}\n      orientation={orientation || undefined}\n      className={cn(\n        separatorVariants({ orientation, variant, size }),\n        className\n      )}\n      {...props}\n    />\n  )\n)\nSeparator.displayName = SeparatorPrimitive.Root.displayName\n\nexport { Separator, separatorVariants }","import * as React from 'react';\nimport { Primitive } from '@radix-ui/react-primitive';\n\n/* -------------------------------------------------------------------------------------------------\n *  Separator\n * -----------------------------------------------------------------------------------------------*/\n\nconst NAME = 'Separator';\nconst DEFAULT_ORIENTATION = 'horizontal';\nconst ORIENTATIONS = ['horizontal', 'vertical'] as const;\n\ntype Orientation = (typeof ORIENTATIONS)[number];\ntype SeparatorElement = React.ComponentRef<typeof Primitive.div>;\nt