'./select'\nimport { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from './tooltip'\nimport { cn } from '../../lib/utils'\nimport {\n  Bold,\n  Italic,\n  Underline,\n  Strikethrough,\n  AlignLeft,\n  AlignCenter,\n  AlignRight,\n  AlignJustify,\n  List,\n  ListOrdered,\n  Quote,\n  Link,\n  Image as ImageIcon,\n  Code,\n  Type,\n  Palette,\n  Undo,\n  Redo,\n  Eye,\n  Edit\n} from 'lucide-react'\n\nexport interface SimpleEditorProps {\n  value?: string\n  onChange?: (value: string) => void\n  placeholder?: string\n  disabled?: boolean\n  className?: string\n  minHeight?: number\n  maxHeight?: number\n  showToolbar?: boolean\n  showPreview?: boolean\n}\n\ninterface ToolbarButtonProps {\n  icon: React.ReactNode\n  tooltip: string\n  active?: boolean\n  onClick: () => void\n  disabled?: boolean\n}\n\nconst ToolbarButton = ({ icon, tooltip, active, onClick, disabled }: ToolbarButtonProps) => (\n  <Tooltip>\n    <TooltipTrigger asChild>\n      <Toggle\n        pressed={active}\n        onPressedChange={() => onClick()}\n        disabled={disabled}\n        className=\"h-8 w-8 p-0\"\n      >\n        {icon}\n      </Toggle>\n    </TooltipTrigger>\n    <TooltipContent>\n      <p>{tooltip}</p>\n    </TooltipContent>\n  </Tooltip>\n)\n\nconst ColorPicker = ({ onColorSelect }: { onColorSelect: (color: string) => void }) => {\n  const colors = [\n    '#000000', '#374151', '#6B7280', '#9CA3AF',\n    '#EF4444', '#F59E0B', '#EAB308', '#22C55E',\n    '#3B82F6', '#6366F1', '#8B5CF6', '#EC4899'\n  ]\n\n  return (\n    <div className=\"grid grid-cols-4 gap-1 p-2\">\n      {colors.map(color => (\n        <button\n          key={color}\n          className=\"w-6 h-6 rounded border-2 border-gray-200 hover:border-gray-400\"\n          style={{ backgroundColor: color }}\n          onClick={() => onColorSelect(color)}\n        />\n      ))}\n    </div>\n  )\n}\n\nexport const SimpleEditor = React.forwardRef<HTMLDivElement, SimpleEditorProps>(\n  ({\n    value = '',\n    onChange,\n    placeholder = 'Start writing...',\n    disabled = false,\n    className,\n    minHeight = 200,\n    maxHeight = 500,\n    showToolbar = true,\n    showPreview = true,\n    ...props\n  }, ref) => {\n    const [content, setContent] = useState(value)\n    const [isPreview, setIsPreview] = useState(false)\n    const [sourceContent, setSourceContent] = useState(value)\n    const [selection, setSelection] = useState<{ start: number; end: number } | null>(null)\n    const editorRef = React.useRef<HTMLDivElement>(null)\n    const sourceRef = React.useRef<HTMLTextAreaElement>(null)\n\n    // Format state tracking\n    const [formatState, setFormatState] = useState({\n      bold: false,\n      italic: false,\n      underline: false,\n      strikethrough: false,\n      alignLeft: true,\n      alignCenter: false,\n      alignRight: false,\n      alignJustify: false,\n      orderedList: false,\n      unorderedList: false,\n      quote: false,\n      code: false\n    })\n\n    const updateContent = useCallback((newContent: string) => {\n      setContent(newContent)\n      onChange?.(newContent)\n    }, [onChange])\n\n    const saveSelection = useCallback(() => {\n      const selection = window.getSelection()\n      if (selection && selection.rangeCount > 0) {\n        return selection.getRangeAt(0)\n      }\n      return null\n    }, [])\n\n    const restoreSelection = useCallback((range: Range | null) => {\n      if (!range) return\n      \n      const selection = window.getSelection()\n      if (selection) {\n        selection.removeAllRanges()\n        selection.addRange(range)\n      }\n    }, [])\n\n    const executeCommand = useCallback((command: string, value?: string) => {\n      if (disabled) return\n      \n      // Focus the editor first\n      if (editorRef.current) {\n        editorRef.current.focus()\n      }\n      \n      // Save current selection before executing command\n      const savedRange = saveSelection()\n      \n      // Execute the command\n      const result = document.execCommand(command, false, value)\n      \n      if (!result) {\n        console.warn(`Command '${command}' failed to execute`)\n      }\n      \n      // Update content state to trigger re-render\n      if (editorRef.current) {\n        const newContent = editorRef.current.innerHTML\n        updateContent(newContent)\n      }\n      \n      // Update format state\n      setFormatState({\n        bold: document.queryCommandState('bold'),\n        italic: document.queryCommandState('italic'),\n        underline: document.queryCommandState('underline'),\n        strikethrough: document.queryCommandState('strikeThrough'),\n        alignLeft: document.queryCommandState('justifyLeft'),\n        alignCenter: document.queryCommandState('justifyCenter'),\n        alignRight: document.queryCommandState('justifyRight'),\n        alignJustify: document.queryCommandState('justifyFull'),\n        orderedList: document.queryCommandState('insertOrderedList'),\n        unorderedList: document.queryCommandState('insertUnorderedList'),\n        quote: document.queryCommandState('formatBlock'),\n        code: document.queryCommandState('formatBlock')\n      })\n      \n      // Keep focus on editor\n      if (editorRef.current) {\n        editorRef.current.focus()\n      }\n    }, [disabled, saveSelection, updateContent])\n\n    const handleInput = useCallback((e: React.FormEvent<HTMLDivElement>) => {\n      const newContent = e.currentTarget.innerHTML\n      updateContent(newContent)\n    }, [updateContent])\n\n    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {\n      // Handle keyboard shortcuts\n      if (e.ctrlKey || e.metaKey) {\n        switch (e.key) {\n          case 'b':\n            e.preventDefault()\n            executeCommand('bold')\n            break\n          case 'i':\n            e.preventDefault()\n            executeCommand('italic')\n            break\n          case 'u':\n            e.preventDefault()\n            executeCommand('underline')\n            break\n          case 'z':\n            e.preventDefault()\n            if (e.shiftKey) {\n              executeCommand('redo')\n            } else {\n              executeCommand('undo')\n            }\n            break\n        }\n      }\n\n      // Handle Tab for indentation\n      if (e.key === 'Tab') {\n        e.preventDefault()\n        executeCommand('insertHTML', '&nbsp;&nbsp;&nbsp;&nbsp;')\n      }\n    }, [executeCommand])\n\n    const insertLink = useCallback(() => {\n      const url = prompt('Enter URL:')\n      if (url) {\n        executeCommand('createLink', url)\n      }\n    }, [executeCommand])\n\n    const insertImage = useCallback(() => {\n      const url = prompt('Enter image URL:')\n      if (url) {\n        executeCommand('insertImage', url)\n      }\n    }, [executeCommand])\n\n    const formatHeading = useCallback((level: string) => {\n      executeCommand('formatBlock', `<h${level}>`)\n    }, [executeCommand])\n\n    const setTextColor = useCallback((color: string) => {\n      // First try the modern way\n      const selection = window.getSelection()\n      if (selection && selection.rangeCount > 0) {\n        const range = selection.getRangeAt(0)\n        const span = document.createElement('span')\n        span.style.color = color\n        \n        try {\n          range.surroundContents(span)\n        } catch (e) {\n          // If surroundContents fails, use execCommand\n          executeCommand('foreColor', color)\n        }\n        \n        // Update content\n        if (editorRef.current) {\n          const newContent = editorRef.current.innerHTML\n          updateContent(newContent)\n        }\n      }\n    }, [executeCommand, updateContent])\n\n    // Convert HTML to plain text for preview\n    const getPlainText = (html: string) => {\n      if (typeof window === 'undefined') {\n        // Server-side: simple regex-based HTML stripping\n        return html\n          .replace(/<[^>]*>/g, '') // Remove HTML tags\n          .replace(/&nbsp;/g, ' ') // Replace &nbsp; with space\n          .replace(/&amp;/g, '&')  // Replace &amp; with &\n          .replace(/&lt;/g, '<')   // Replace &lt; with <\n          .replace(/&gt;/g, '>')   // Replace &gt; with >\n          .replace(/&quot;/g, '\"') // Replace &quot; with \"\n          .replace(/&#39;/g, \"'\")  // Replace &#39; with '\n      }\n      // Client-side: use DOM for accurate conversion\n      const div = document.createElement('div')\n      div.innerHTML = html\n      return div.textContent || div.innerText || ''\n    }\n\n    React.useEffect(() => {\n      if (editorRef.current && content && content !== editorRef.current.innerHTML) {\n        editorRef.current.innerHTML = content\n      }\n    }, [content])\n\n    // Sync source content when value prop changes\n    React.useEffect(() => {\n      if (value !== undefined && value !== content) {\n        setContent(value)\n        setSourceContent(value)\n      }\n    }, [value, content])\n\n    const toolbar = showToolbar && (\n      <TooltipProvider>\n        <motion.div\n          className=\"flex items-center gap-1 p-2 border-b bg-gray-50/50 dark:bg-zinc-800/50 backdrop-blur-sm\"\n          initial={{ opacity: 0, y: -10 }}\n          animate={{ opacity: 1, y: 0 }}\n        >\n        {/* Text Formatting */}\n        {!isPreview && (\n          <>\n            <div className=\"flex items-center gap-1\">\n          <ToolbarButton\n            icon={<Bold className=\"h-3 w-3\" />}\n            tooltip=\"Bold (Ctrl+B)\"\n            active={formatState.bold}\n            onClick={() => executeCommand('bold')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<Italic className=\"h-3 w-3\" />}\n            tooltip=\"Italic (Ctrl+I)\"\n            active={formatState.italic}\n            onClick={() => executeCommand('italic')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<Underline className=\"h-3 w-3\" />}\n            tooltip=\"Underline (Ctrl+U)\"\n            active={formatState.underline}\n            onClick={() => executeCommand('underline')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<Strikethrough className=\"h-3 w-3\" />}\n            tooltip=\"Strikethrough\"\n            active={formatState.strikethrough}\n            onClick={() => executeCommand('strikeThrough')}\n            disabled={disabled}\n          />\n        </div>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Font Size / Heading */}\n        <Select \n          onValueChange={(value) => {\n            if (value.startsWith('h')) {\n              formatHeading(value.substring(1))\n            } else if (value === 'normal') {\n              executeCommand('formatBlock', 'p')\n            } else {\n              executeCommand('fontSize', value)\n            }\n          }} \n          disabled={disabled}\n        >\n          <SelectTrigger className=\"w-24 h-8\">\n            <SelectValue placeholder=\"Size\" />\n          </SelectTrigger>\n          <SelectContent>\n            <SelectItem value=\"1\">Small</SelectItem>\n            <SelectItem value=\"3\">Normal</SelectItem>\n            <SelectItem value=\"5\">Large</SelectItem>\n            <SelectItem value=\"7\">X-Large</SelectItem>\n            <Separator className=\"my-1\" />\n            <SelectItem value=\"h1\">Heading 1</SelectItem>\n            <SelectItem value=\"h2\">Heading 2</SelectItem>\n            <SelectItem value=\"h3\">Heading 3</SelectItem>\n            <SelectItem value=\"h4\">Heading 4</SelectItem>\n            <SelectItem value=\"h5\">Heading 5</SelectItem>\n            <SelectItem value=\"h6\">Heading 6</SelectItem>\n          </SelectContent>\n        </Select>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Alignment */}\n        <div className=\"flex items-center gap-1\">\n          <ToolbarButton\n            icon={<AlignLeft className=\"h-3 w-3\" />}\n            tooltip=\"Align Left\"\n            active={formatState.alignLeft}\n            onClick={() => executeCommand('justifyLeft')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<AlignCenter className=\"h-3 w-3\" />}\n            tooltip=\"Align Center\"\n            active={formatState.alignCenter}\n            onClick={() => executeCommand('justifyCenter')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<AlignRight className=\"h-3 w-3\" />}\n            tooltip=\"Align Right\"\n            active={formatState.alignRight}\n            onClick={() => executeCommand('justifyRight')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<AlignJustify className=\"h-3 w-3\" />}\n            tooltip=\"Justify\"\n            active={formatState.alignJustify}\n            onClick={() => executeCommand('justifyFull')}\n            disabled={disabled}\n          />\n        </div>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Lists */}\n        <div className=\"flex items-center gap-1\">\n          <ToolbarButton\n            icon={<List className=\"h-3 w-3\" />}\n            tooltip=\"Bullet List\"\n            active={formatState.unorderedList}\n            onClick={() => executeCommand('insertUnorderedList')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<ListOrdered className=\"h-3 w-3\" />}\n            tooltip=\"Numbered List\"\n            active={formatState.orderedList}\n            onClick={() => executeCommand('insertOrderedList')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<Quote className=\"h-3 w-3\" />}\n            tooltip=\"Quote\"\n            active={formatState.quote}\n            onClick={() => executeCommand('formatBlock', 'blockquote')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<Code className=\"h-3 w-3\" />}\n            tooltip=\"Code Block\"\n            active={formatState.code}\n            onClick={() => executeCommand('formatBlock', 'pre')}\n            disabled={disabled}\n          />\n        </div>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Indentation */}\n        <div className=\"flex items-center gap-1\">\n          <ToolbarButton\n            icon={<span className=\"text-xs font-mono\">←</span>}\n            tooltip=\"Decrease Indent\"\n            onClick={() => executeCommand('outdent')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<span className=\"text-xs font-mono\">→</span>}\n            tooltip=\"Increase Indent\"\n            onClick={() => executeCommand('indent')}\n            disabled={disabled}\n          />\n        </div>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Insert */}\n        <div className=\"flex items-center gap-1\">\n          <ToolbarButton\n            icon={<Link className=\"h-3 w-3\" />}\n            tooltip=\"Insert Link\"\n            onClick={insertLink}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<ImageIcon className=\"h-3 w-3\" />}\n            tooltip=\"Insert Image\"\n            onClick={insertImage}\n            disabled={disabled}\n          />\n        </div>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Color */}\n        <Popover>\n          <PopoverTrigger asChild>\n            <Button \n              variant=\"ghost\" \n              size=\"sm\" \n              className=\"h-8 w-8 p-0\" \n              disabled={disabled}\n              title=\"Text Color\"\n            >\n              <Palette className=\"h-3 w-3\" />\n            </Button>\n          </PopoverTrigger>\n          <PopoverContent className=\"w-auto p-0\">\n            <ColorPicker onColorSelect={setTextColor} />\n          </PopoverContent>\n        </Popover>\n\n        <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />\n\n        {/* Undo/Redo */}\n        <div className=\"flex items-center gap-1\">\n          <ToolbarButton\n            icon={<Undo className=\"h-3 w-3\" />}\n            tooltip=\"Undo (Ctrl+Z)\"\n            onClick={() => executeCommand('undo')}\n            disabled={disabled}\n          />\n          <ToolbarButton\n            icon={<Redo className=\"h-3 w-3\" />}\n            tooltip=\"Redo (Ctrl+Shift+Z)\"\n            onClick={() => executeCommand('redo')}\n            disabled={disabled}\n          />\n        </div>\n\n          </>\n        )}\n\n        {/* Preview Toggle */}\n        {showPreview && (\n          <>\n            {!isPreview && <Separator orientation=\"vertical\" className=\"h-6 bg-gray-300 dark:bg-zinc-600\" />}\n            <ToolbarButton\n              icon={isPreview ? <Edit className=\"h-3 w-3\" /> : <Eye className=\"h-3 w-3\" />}\n              tooltip={isPreview ? \"Edit Mode\" : \"View Source Code\"}\n              active={isPreview}\n              onClick={() => {\n                if (isPreview) {\n                  // Apply source changes to content when switching back to edit mode\n                  updateContent(sourceContent)\n                } else {\n                  // Update source content when switching to preview mode\n                  setSourceContent(content)\n                }\n                setIsPreview(!isPreview)\n              }}\n              disabled={disabled}\n            />\n          </>\n        )}\n        </motion.div>\n      </TooltipProvider>\n    )\n\n    return (\n      <div\n        ref={ref}\n        className={cn(\n          \"border border-gray-200 dark:border-zinc-700 rounded-lg overflow-hidden focus-within:ring-2 focus-within:ring-ring focus-within:border-transparent\",\n          disabled && \"opacity-50 cursor-not-allowed\",\n          className\n        )}\n        {...props}\n      >\n        {toolbar}\n\n        <div className=\"relative\">\n          {isPreview ? (\n            <motion.div\n              initial={{ opacity: 0 }}\n              animate={{ opacity: 1 }}\n              className=\"bg-slate-50 dark:bg-zinc-900/95\"\n              style={{ minHeight, maxHeight, overflow: 'auto' }}\n            >\n              <textarea\n                ref={sourceRef}\n                value={sourceContent}\n                onChange={(e) => setSourceContent(e.target.value)}\n                className=\"w-full h-full bg-transparent p-4 font-mono text-sm text-gray-900 dark:text-gray-100 resize-none focus:outline-none\"\n                style={{ minHeight: minHeight - 32 }}\n                disabled={disabled}\n                placeholder=\"HTML source code...\"\n              />\n            </motion.div>\n          ) : (\n            <motion.div\n              ref={editorRef}\n              contentEditable={!disabled}\n              suppressContentEditableWarning\n              className={cn(\n                \"p-4 outline-none prose prose-sm dark:prose-invert max-w-none overflow-y-auto\",\n                \"bg-slate-50 dark:bg-zinc-900/95\",\n                \"text-gray-900 dark:text-gray-100\",\n                \"focus:ring-0\",\n                \"[&_h1]:text-3xl [&_h1]:font-bold [&_h1]:mb-4\",\n                \"[&_h2]:text-2xl [&_h2]:font-bold [&_h2]:mb-3\",\n                \"[&_h3]:text-xl [&_h3]:font-bold [&_h3]:mb-2\",\n                \"[&_h4]:text-lg [&_h4]:font-bold [&_h4]:mb-2\",\n                \"[&_h5]:text-base [&_h5]:font-bold [&_h5]:mb-1\",\n                \"[&_h6]:text-sm [&_h6]:font-bold [&_h6]:mb-1\",\n                \"[&_ul]:list-disc [&_ul]:pl-6 [&_ul]:mb-4\",\n                \"[&_ol]:list-decimal [&_ol]:pl-6 [&_ol]:mb-4\",\n                \"[&_li]:mb-1\",\n                \"[&_blockquote]:border-l-4 [&_blockquote]:border-gray-300 [&_blockquote]:pl-4 [&_blockquote]:italic\",\n                \"[&_pre]:bg-gray-100 [&_pre]:dark:bg-gray-800 [&_pre]:p-4 [&_pre]:rounded [&_pre]:overflow-x-auto\"\n              )}\n              style={{ minHeight, maxHeight }}\n              onInput={handleInput}\n              onKeyDown={handleKeyDown}\n              data-placeholder={placeholder}\n              initial={{ opacity: 0 }}\n              animate={{ opacity: 1 }}\n            />\n          )}\n\n          {/* Placeholder */}\n          {!content && !isPreview && (\n            <div\n              className=\"absolute top-4 left-4 text-muted-foreground pointer-events-none\"\n              style={{ fontSize: '16px' }}\n            >\n              {placeholder}\n            </div>\n          )}\n        </div>\n\n        {/* Character Count */}\n        <div className=\"px-4 py-2 border-t bg-gray-50/50 dark:bg-zinc-800/50 backdrop-blur-sm text-xs text-gray-600 dark:text-gray-400\">\n          <CharacterCount content={content} />\n        </div>\n      </div>\n    )\n  }\n)\n\nSimpleEditor.displayName = \"SimpleEditor\"\n\n// Character count component to avoid hydration issues\nconst CharacterCount = ({ content }: { content: string }) => {\n  const [count, setCount] = useState(0)\n  \n  useEffect(() => {\n    const getPlainText = (html: string) => {\n      const div = document.createElement('div')\n      div.innerHTML = html\n      return div.textContent || div.innerText || ''\n    }\n    setCount(getPlainText(content).length)\n  }, [content])\n  \n  return <>{count} characters</>\n}","\"use client\"\n\nimport * as React from \"react\"\nimport * as TogglePrimitive from \"@radix-ui/react-toggle\"\nimport { cva, type VariantProps } from \"class-variance-authority\"\n\nimport { cn } from \"../../lib/utils\"\n\nconst toggleVariants = cva(\n  \"inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-transparent\",\n        outline:\n          \"border border-input bg-transparent hover:bg-accent hover:text-accent-foreground\",\n      },\n      size: {\n        default: \"h-10 px-3\",\n        sm: \"h-9 px-2.5\",\n        lg: \"h-11 px-5\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n\nexport interface ToggleProps extends React.ComponentPropsWithoutRef<typeof TogglePrimitive.Root>, VariantProps<typeof toggleVariants> {}\n\nconst Toggle = React.forwardRef<\n  React.ElementRef<typeof TogglePrimitive.Root>,\n  ToggleProps\n>(({ className, variant, size, ...props }, ref) => (\n  <TogglePrimitive.Root\n    ref={ref}\n    className={cn(\"moonui-theme\", toggleVariants({ variant, size, className }))}\n    {...props}\n  />\n))\n\nToggle.displayName = TogglePrimitive.Root.displayName\n\nexport { Toggle, toggleVariants }","import * as React from 'react';\nimport { composeEventHandlers } from '@radix-ui/primitive';\nimport { useControllableState } from '@radix-ui/react-use-controllable-state';\nimport { Primitive } from '@radix-ui/react-primitive';\n\n/* -------------------------------------------------------------------------------------------------\n * Toggle\n * -----------------------------------------------------------------------------------------------*/\n\nconst NAME = 'Toggle';\n\ntype ToggleElement = React.ComponentRef<typeof Primitive.button>;\ntype PrimitiveButtonProps = React.ComponentPropsWithoutRef<typeof Primitive.button>;\ninterface ToggleProps extends PrimitiveButtonProps {\n  /**\n   * The controlled state of the toggle.\n   */\n  pressed?: boolean;\n  /**\n   * The state of the toggle when initially rendered. Use `defaultPressed`\n   * if you do not need to control the state of the toggle.\n   * @defaultValue false\n   */\n  defaultPressed?: boolean;\n  /**\n   * The callback that fires when the state of the toggle changes.\n   */\n  onPressedChange?(pressed: boolean): void;\n}\n\nconst Toggle = React.forwardRef<ToggleElement, ToggleProps>((props, forwardedRef) => {\n  const { pressed: pressedProp, defaultPressed, onPressedChange, ...buttonProps } = props;\n\n  const [pressed, setPressed] = useControllableState({\n    prop: pressedProp,\n    onChange: onPressedChange,\n    defaultProp: defaultPressed ?? false,\n    caller: NAME,\n  });\n\n  return (\n    <Primitive.button\n      type=\"button\"\n      aria-pressed={pressed}\n      data-state={pressed ? 'on' : 'off'}\n      data-disabled={props.disabled ? '' : undefined}\n      {...buttonProps}\n      ref={forwardedRef}\n      onClick={composeEventHandlers(props.onClick, () => {\n        if (!props.disabled) {\n          setPressed(!pressed);\n        }\n      })}\n    />\n  );\n});\n\nToggle.displayName = NAME;\n\n/* ---------------------------------------------------------------------------------------------- */\n\nconst Root = Toggle;\n\nexport {\n  Toggle,\n  //\n  Root,\n};\nexport type { ToggleProps };\n","\"use client\"\n\nimport * as React from \"react\"\nimport * as TooltipPrimitive from \"@radix-ui/react-tooltip\"\nimport { cva, type VariantProps } from \"class-variance-authority\"\n\nimport { cn } from \"../../lib/utils\"\n\nconst TooltipProvider = TooltipPrimitive.Provider\n\nconst tooltipVariants = cva(\n  \"z-50 overflow-hidden rounded-md border bg-popover px-3 py-1.5 text-sm text-popover-foreground shadow-md animate-in fade-in-0 zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground\",\n        secondary: \"bg-secondary text-secondary-foreground\",\n        success: \"bg-green-500 text-white border-green-600\",\n        warning: \"bg-yellow-500 text-white border-yellow-600\",\n        destructive: \"bg-destructive text-destructive-foreground\",\n        info: \"bg-blue-500 text-white border-blue-600\",\n      },\n      size: {\n        sm: \"px-2 py-1 text-xs\",\n        md: \"px-3 py-1.5 text-sm\",\n        lg: \"px-4 py-2 text-base\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"md\",\n    },\n  }\n)\n\nconst Tooltip = TooltipPrimitive.Root\n\nconst TooltipTrigger = TooltipPrimitive.Trigger\n\nconst TooltipArrow = React.forwardRef<\n  React.ElementRef<typeof TooltipPrimitive.Arrow>,\n  React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Arrow>\n>(({ className, ...props }, ref) => (\n  <TooltipPrimitive.Arrow\n    ref={ref}\n    className={cn(\"moonui-theme\", \"fill-current\", className)}\n    {...props}\n  />\n))\nTooltipArrow.displayName = TooltipPrimitive.Arrow.displayName\n\nexport interface TooltipContentProps\n  extends React.ComponentPropsWithoutRef<typeof TooltipPrimitive.Content>,\n    VariantProps<typeof tooltipVariants> {\n  showArrow?: boolean\n}\n\nconst TooltipContent = React.forwardRef<\n  React.ElementRef<typeof TooltipPrimitive.Content>,\n  TooltipContentProps\n>(({ className, variant, size, showArrow = false, sideOffset = 4, ...props }, ref) => (\n  <TooltipPrimitive.Content\n    ref={ref}\n    sideOffset={sideOffset}\n    className={cn(\"moonui-theme\", tooltipVariants({ variant, size }), className)}\n    {...props}\n  >\n    {props.children}\n    {sho