er the content is loaded\n   */\n  isLoaded?: boolean;\n  /**\n   * Content to show when loaded\n   */\n  children?: React.ReactNode;\n  /**\n   * Fade-in animation duration in ms\n   */\n  fadeInDuration?: number;\n  /**\n   * Use motion animation for loading state\n   */\n  motion?: boolean;\n}\n\nexport const Skeleton = React.forwardRef<HTMLDivElement, SkeletonProps>(\n  ({ \n    className,\n    variant,\n    size,\n    shape,\n    animation,\n    height,\n    width,\n    isLoaded = false,\n    children,\n    fadeInDuration = 400,\n    motion: useMotion = false,\n    style,\n    ...props \n  }, ref) => {\n    // Filter out HTML event handlers that conflict with Framer Motion\n    const { \n      onDrag, \n      onDragEnd, \n      onDragStart,\n      onAnimationStart,\n      onAnimationEnd,\n      onAnimationIteration,\n      ...filteredProps \n    } = props;\n    \n    // Show content when loaded\n    if (isLoaded && children) {\n      if (useMotion) {\n        return (\n          <motion.div\n            ref={ref}\n            initial={{ opacity: 0 }}\n            animate={{ opacity: 1 }}\n            transition={{ duration: fadeInDuration / 1000 }}\n            className={cn(\"moonui-theme\", className)}\n            style={{\n              height,\n              width,\n              ...style,\n            }}\n            {...filteredProps}\n          >\n            {children}\n          </motion.div>\n        );\n      }\n      \n      return (\n        <div\n          ref={ref}\n          className={cn(\"moonui-theme\", \"animate-fade-in\", className)}\n          style={{\n            animationDuration: `${fadeInDuration}ms`,\n            height,\n            width,\n            ...style,\n          }}\n          {...props}\n        >\n          {children}\n        </div>\n      );\n    }\n\n    const SkeletonElement = useMotion ? motion.div : \"div\";\n    \n    return (\n      <SkeletonElement\n        ref={ref}\n        className={cn(\n          \"moonui-