Start = (e: React.TouchEvent) => {\n      if (disabled) return\n      setStartX(e.touches[0].clientX)\n      setIsSwiping(true)\n    }\n\n    const handleTouchMove = (e: React.TouchEvent) => {\n      if (disabled || !isSwiping) return\n      setCurrentX(e.touches[0].clientX)\n    }\n\n    const handleTouchEnd = () => {\n      if (disabled || !isSwiping) return\n      \n      const deltaX = currentX - startX\n      \n      if (Math.abs(deltaX) > threshold) {\n        if (deltaX > 0 && onSwipeRight) {\n          onSwipeRight()\n        } else if (deltaX < 0 && onSwipeLeft) {\n          onSwipeLeft()\n        }\n      }\n      \n      setIsSwiping(false)\n      setCurrentX(0)\n      setStartX(0)\n    }\n\n    return (\n      <div\n        ref={ref}\n        className={cn(\n          \"touch-pan-y select-none transition-transform duration-200\",\n          isSwiping && \"cursor-grabbing\",\n          className\n        )}\n        onTouchStart={handleTouchStart}\n        onTouchMove={handleTouchMove}\n        onTouchEnd={handleTouchEnd}\n        {...props}\n      >\n        {children}\n      </div>\n    )\n  }\n)\n\nSwipeableCard.displayName = \"SwipeableCard\"","\"use client\"\n\nimport * as React from \"react\"\nimport * as SwitchPrimitives from \"@radix-ui/react-switch\"\n\nimport { cn } from \"../../lib/utils\"\n\ntype SwitchSize = \"sm\" | \"md\" | \"lg\";\ntype SwitchVariant = \"primary\" | \"success\" | \"warning\" | \"danger\" | \"secondary\";\n\nexport interface SwitchProps extends React.ComponentPropsWithoutRef<typeof SwitchPrimitives.Root> {\n  /** Switch boyutu */\n  size?: SwitchSize;\n  /** Switch renk varyantı */\n  variant?: SwitchVariant;\n  /** Yükleniyor durumunu gösterir */\n  loading?: boolean;\n  /** Sol tarafta gösterilecek ikon */\n  leftIcon?: React.ReactNode;\n  /** Sağ tarafta gösterilecek ikon */\n  rightIcon?: React.ReactNode;\n  /** Switch açıklaması */\n  description?: string;\n}\n\nconst Switch = React.forwardRef<\n  React.ElementRef<type